const inputData = $input.item.json;
const config = $('Set Sport Config').item.json;
const sportId = config.basketballSportId;
const sportName = 'Basketball';

const events = [];
const sports = inputData.reply.sports;

for (const sid in sports) {
  if (sid !== sportId) continue;

  const sport = sports[sid];

  for (const champId in sport.chmps) {
    const championship = sport.chmps[champId];
    const leagueName = championship.name_ch.replace(new RegExp(sportName + '\\.\\s*', 'i'), '').trimStart();

    for (const eventId in championship.evts) {
      const evt = championship.evts[eventId];
      if(evt.fut === 1 || evt.is_stat === 1) continue;

      const date = new Date((evt.date_ev * 1000) + (8 * 60 * 60 * 1000));
      const eventDate = date.toISOString().split('T')[0];
      const eventTime = date.toISOString().slice(0, 19).replace('T', ' ');

      events.push({
        eventId: evt.id_ev,
        eventDate: eventDate,
        eventDateTime: eventTime,
        leagueGroupId: evt.id_ch_gl,
        leagueId: evt.cn_ch,
        league: leagueName,
        homeId: evt.id_ht,
        home: evt.name_ht,
        awayId: evt.id_at,
        away: evt.name_at,
        homeCountry: evt.iso_f,
        awayCountry: evt.iso_s,
        status: evt.st_ev,
        future: evt.fut,
        statistics: evt.is_stat
      });
    }
  }
}

const groupedByDate = events.reduce((acc, event) => {
  const date = event.eventDate;
  if (!acc[date]) {
    acc[date] = [];
  }
  acc[date].push(event);
  return acc;
}, {});

return Object.entries(groupedByDate).map(([date, events]) => ({
  json: {
    sportType: 'Basketball',
    sheetId: config.basketballSheetId,
    eventDate: date,
    eventCount: events.length,
    events: events
  }
}));

